import * as d3 from 'd3';
import { Sel, drawLabel, drawArrow } from '../primitives';
import { ComputationGraph } from '../../graph/types';
import { ComponentDef } from '../../components/types';

export interface EmbeddingStep {
  id: number;
  label: string;
  shortLabel: string;
  formula: string;
  explanation: string;
  code: { title: string; lines: string[] };
  svgGroup: string;
  color: string;
  fill: string;
}

export const EMBEDDING_STEPS: EmbeddingStep[] = [
  {
    id: 1,
    label: 'Token IDs → Embedding Lookup',
    shortLabel: 'Token Lookup',
    formula: 'e = E[token_id]',
    explanation:
      'Each integer token ID indexes into the embedding matrix E ∈ ℝ^(vocab × d_model), ' +
      'extracting a dense row vector. This is a simple gather — no multiply, just a table lookup. ' +
      'The embedding matrix is the largest parameter block in small models (vocab × d_model ≈ 16M for vocab=32k, d=512).',
    code: {
      title: 'Token Embedding Lookup',
      lines: [
        'self.embed = nn.Embedding(vocab_size, d_model)',
        '# forward:',
        'e = self.embed(token_ids)  # [B, seq, d_model]',
      ],
    },
    svgGroup: 'step-token',
    color: '#16a34a',
    fill: '#dcfce7',
  },
  {
    id: 2,
    label: 'Scale by √d_model',
    shortLabel: 'Scale',
    formula: 'e = e × √d_model',
    explanation:
      'Embeddings are randomly initialized with small variance (~1/√d_model via normal init). ' +
      'Multiplying by √d_model restores the variance to ~1, preventing the embeddings from being ' +
      'dominated by the positional encoding which has fixed amplitude O(1). ' +
      'Used in "Attention Is All You Need" (Vaswani et al. 2017).',
    code: {
      title: 'Embedding Scale',
      lines: [
        'import math',
        'scale = math.sqrt(d_model)',
        'e = e * scale  # [B, seq, d_model]',
      ],
    },
    svgGroup: 'step-scale',
    color: '#d97706',
    fill: '#fef3c7',
  },
  {
    id: 3,
    label: 'Add Positional Encoding (Sinusoidal / Learned)',
    shortLabel: 'Pos Encoding',
    formula: 'x = e + PE(pos)',
    explanation:
      'Transformers have no recurrence, so position must be injected explicitly. ' +
      'Sinusoidal PE: PE(pos, 2i) = sin(pos/10000^(2i/d_model)), PE(pos, 2i+1) = cos(…). ' +
      'Learned PE: trainable matrix P ∈ ℝ^(max_seq × d_model). ' +
      'Both add position info before the first attention layer. ' +
      'Used in BERT, GPT-2, T5-relative. RoPE/ALiBi skip this step entirely.',
    code: {
      title: 'Sinusoidal Positional Encoding',
      lines: [
        '# Pre-computed sinusoidal table',
        'pos = torch.arange(seq_len).unsqueeze(1)  # [seq, 1]',
        'dim = torch.arange(0, d_model, 2)         # [d/2]',
        'angles = pos / 10000 ** (dim / d_model)',
        'PE = torch.zeros(seq_len, d_model)',
        'PE[:, 0::2] = torch.sin(angles)',
        'PE[:, 1::2] = torch.cos(angles)',
        'x = e + PE  # [B, seq, d_model]',
      ],
    },
    svgGroup: 'step-pe',
    color: '#2563eb',
    fill: '#dbeafe',
  },
  {
    id: 4,
    label: 'RoPE: Rotate Q/K in Attention (Not Here)',
    shortLabel: 'RoPE / ALiBi',
    formula: 'q_rot = q ⊗ cos(mθ) + q_⊥ ⊗ sin(mθ)',
    explanation:
      'RoPE (Rotary Position Embedding) encodes position inside the attention computation, not at the embedding layer. ' +
      'It rotates Q and K vectors in d/2 2D planes by an angle proportional to absolute position. ' +
      'The result: attention scores depend only on relative position (q_m · k_n = f(m-n)), ' +
      'with full generalization to longer sequences. Default in Llama, Mistral, Qwen, Gemma, DeepSeek. ' +
      'ALiBi instead subtracts a linear bias from attention logits based on distance.',
    code: {
      title: 'RoPE Application (inside Attention)',
      lines: [
        '# θ_i = 1 / 10000^(2i/d_head)',
        'def rotate_half(x):',
        '    x1, x2 = x[..., ::2], x[..., 1::2]',
        '    return torch.stack([-x2, x1], dim=-1).flatten(-2)',
        '',
        'def apply_rope(x, cos, sin):',
        '    return x * cos + rotate_half(x) * sin',
        '',
        '# Applied to Q and K, not to embeddings',
        'q = apply_rope(q, cos[pos], sin[pos])',
        'k = apply_rope(k, cos[pos], sin[pos])',
      ],
    },
    svgGroup: 'step-rope',
    color: '#7c3aed',
    fill: '#ede9fe',
  },
];

export function renderEmbeddingDetailed(
  g: d3.Selection<SVGGElement, unknown, null, undefined>,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: EmbeddingStep[] } {
  const posEncoding = String(params['pos_encoding'] ?? 'rope');
  const totalW = 560;
  const cx = totalW / 2;

  // Filter relevant steps for current pos_encoding
  const showPE = posEncoding === 'sinusoidal' || posEncoding === 'learned';
  const showRope = posEncoding === 'rope' || posEncoding === 'alibi';

  let y = 30;

  // ── Title ──────────────────────────────────────────────────────────────────
  drawLabel(g as unknown as Sel, cx, y, 'Embedding Layer', { size: 15, weight: '700', color: 'var(--text)' });
  y += 18;
  drawLabel(g as unknown as Sel, cx, y, `pos_encoding = ${posEncoding}`, { size: 10, color: 'var(--text-muted)' });
  y += 30;

  // ── Input tensor ──────────────────────────────────────────────────────────
  drawInputBox(g as unknown as Sel, cx - 110, y, 220, 34, 'token_ids', '[B, seq]', '#16a34a');
  y += 50;

  // ── Step 1: Token Lookup ──────────────────────────────────────────────────
  const step1 = g.append('g').attr('class', 'step-node step-token').attr('data-step', '1');
  drawArrowDown(g as unknown as Sel, cx, y - 14, y - 2);
  drawNodeBox(step1 as unknown as Sel, cx - 110, y, 220, 44, 'Token Embedding Lookup', 'e = E [ token_id ]', '#16a34a', '#dcfce7');

  // Embedding matrix annotation
  drawMatrixAnnotation(g as unknown as Sel, cx + 120, y + 4, 100, 36, 'E', '[vocab × d_model]', '#16a34a', '#dcfce7');
  drawArrow(g as unknown as Sel, cx + 118, y + 22, cx + 112, y + 22, { color: '#16a34a' });
  y += 60;

  // ── Step 2: Scale ─────────────────────────────────────────────────────────
  const step2 = g.append('g').attr('class', 'step-node step-scale').attr('data-step', '2');
  drawArrowDown(g as unknown as Sel, cx, y - 14, y - 2);
  drawNodeBox(step2 as unknown as Sel, cx - 90, y, 180, 40, 'Scale', 'e = e × √d_model', '#d97706', '#fef3c7');
  y += 56;

  // ── Step 3 or 4 depending on variant ─────────────────────────────────────
  if (showPE) {
    const step3 = g.append('g').attr('class', 'step-node step-pe').attr('data-step', '3');
    drawArrowDown(g as unknown as Sel, cx, y - 14, y - 2);
    drawNodeBox(step3 as unknown as Sel, cx - 110, y, 220, 44, 'Add Positional Encoding', 'x = e + PE( pos )', '#2563eb', '#dbeafe');
    drawMatrixAnnotation(g as unknown as Sel, cx + 120, y + 4, 100, 36, 'PE', '[max_seq × d_model]', '#2563eb', '#dbeafe');
    drawArrow(g as unknown as Sel, cx + 118, y + 22, cx + 112, y + 22, { color: '#2563eb' });
    y += 60;
  }

  if (showRope) {
    const step4 = g.append('g').attr('class', 'step-node step-rope').attr('data-step', '4');
    drawArrowDown(g as unknown as Sel, cx, y - 14, y - 2);
    drawDashedBox(step4 as unknown as Sel, cx - 110, y, 220, 44, 'RoPE/ALiBi in Attention →', 'positional info applied to Q/K later', '#7c3aed', '#ede9fe');
    y += 60;
  }

  // ── Output tensor ─────────────────────────────────────────────────────────
  drawArrowDown(g as unknown as Sel, cx, y - 14, y - 2);
  drawInputBox(g as unknown as Sel, cx - 110, y, 220, 34, 'embeddings x', '[B, seq, d_model]', '#16a34a');
  y += 50;

  // ── Param / FLOPs summary ─────────────────────────────────────────────────
  drawLabel(g as unknown as Sel, cx, y + 6, 'Params: vocab × d_model', {
    size: 10,
    color: '#2563eb',
    weight: '600',
  });
  drawLabel(g as unknown as Sel, cx, y + 22, 'FLOPs: O(seq × d_model) for scale', {
    size: 10,
    color: 'var(--text-muted)',
  });
  y += 40;

  return { width: totalW, height: y + 20, steps: EMBEDDING_STEPS };
}

// ── Helpers ──────────────────────────────────────────────────────────────────

function drawArrowDown(g: Sel, cx: number, y1: number, y2: number): void {
  drawArrow(g, cx, y1, cx, y2, { color: '#94a3b8' });
}

function drawInputBox(
  g: Sel,
  x: number,
  y: number,
  w: number,
  h: number,
  label: string,
  shape: string,
  color: string
): void {
  const group = (g as unknown as d3.Selection<SVGGElement, unknown, null, undefined>)
    .append('g')
    .attr('transform', `translate(${x},${y})`);
  group
    .append('rect')
    .attr('width', w)
    .attr('height', h)
    .attr('rx', 8)
    .attr('fill', 'var(--surface)')
    .attr('stroke', color)
    .attr('stroke-width', 2)
    .attr('stroke-dasharray', '6,3');
  drawLabel(group as unknown as Sel, w / 2, h / 2 - 6, label, {
    size: 11,
    weight: '700',
    color: 'var(--text)',
  });
  drawLabel(group as unknown as Sel, w / 2, h / 2 + 8, shape, {
    size: 9,
    font: 'monospace',
    color: 'var(--text-muted)',
  });
}

function drawNodeBox(
  g: Sel,
  x: number,
  y: number,
  w: number,
  h: number,
  label: string,
  formula: string,
  stroke: string,
  fill: string
): void {
  const group = (g as unknown as d3.Selection<SVGGElement, unknown, null, undefined>)
    .append('g')
    .attr('transform', `translate(${x},${y})`);
  group
    .append('rect')
    .attr('width', w)
    .attr('height', h)
    .attr('rx', 8)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 2);
  drawLabel(group as unknown as Sel, w / 2, h / 2 - 7, label, {
    size: 12,
    weight: '700',
    color: 'var(--text)',
  });
  drawLabel(group as unknown as Sel, w / 2, h / 2 + 9, formula, {
    size: 9,
    font: 'monospace',
    color: stroke,
  });
}

function drawDashedBox(
  g: Sel,
  x: number,
  y: number,
  w: number,
  h: number,
  label: string,
  sublabel: string,
  stroke: string,
  fill: string
): void {
  const group = (g as unknown as d3.Selection<SVGGElement, unknown, null, undefined>)
    .append('g')
    .attr('transform', `translate(${x},${y})`);
  group
    .append('rect')
    .attr('width', w)
    .attr('height', h)
    .attr('rx', 8)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5)
    .attr('stroke-dasharray', '6,4')
    .attr('opacity', 0.8);
  drawLabel(group as unknown as Sel, w / 2, h / 2 - 7, label, {
    size: 11,
    weight: '600',
    color: stroke,
  });
  drawLabel(group as unknown as Sel, w / 2, h / 2 + 9, sublabel, {
    size: 9,
    color: 'var(--text-muted)',
  });
}

function drawMatrixAnnotation(
  g: Sel,
  x: number,
  y: number,
  w: number,
  h: number,
  label: string,
  sublabel: string,
  stroke: string,
  fill: string
): void {
  const group = (g as unknown as d3.Selection<SVGGElement, unknown, null, undefined>)
    .append('g')
    .attr('transform', `translate(${x},${y})`);
  group
    .append('rect')
    .attr('width', w)
    .attr('height', h)
    .attr('rx', 6)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5);
  // simple cell grid
  const cols = 6;
  const rows = 4;
  let seed = 42;
  const lcg = () => {
    seed = (seed * 1664525 + 1013904223) & 0xffffffff;
    return (seed >>> 0) / 0xffffffff;
  };
  const cw = (w - 2) / cols;
  const ch = (h - 2) / rows;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      group
        .append('rect')
        .attr('x', 1 + c * cw)
        .attr('y', 1 + r * ch)
        .attr('width', cw - 0.5)
        .attr('height', ch - 0.5)
        .attr('fill', stroke)
        .attr('opacity', 0.05 + lcg() * 0.2);
    }
  }
  drawLabel(group as unknown as Sel, w / 2, h / 2 - 6, label, {
    size: 11,
    weight: '700',
    color: 'var(--text)',
  });
  drawLabel(group as unknown as Sel, w / 2, h / 2 + 7, sublabel, {
    size: 7,
    font: 'monospace',
    color: stroke,
  });
}
